import os, time, csv
F = project.folder.replace('\\', '/') + '/'
TOX = F + 'genesis_7140_zenith_v1_3_1.tox'
LOG = F + 'genesis_live_v1_3_1_log.txt'
def log(*a):
    with open(LOG, 'a', encoding='utf-8') as f: f.write(time.strftime('%Y-%m-%d %H:%M:%S ') + ' '.join(str(x) for x in a) + '\n')
def table(name, path):
    p = op('/project1'); t = p.op(name) or p.create(tableDAT, name); t.clear()
    for r in csv.reader(open(path, encoding='utf-8')): t.appendRow(r)
    return t
def go():
    try:
        a = table('dmxmap', F + 'DMX_1128_Constant_Beam_Map.csv'); b = table('nodes', F + 'touchdesigner_nodes.csv')
        log('tables', a.numRows, 'x', a.numCols, '|', b.numRows, 'x', b.numCols)
        p = op('/project1'); z = p.op('GENESIS_7140_ZENITH') or p.loadTox(TOX)
        z.name = 'GENESIS_7140_ZENITH'
        z.par.w = 1280; z.par.h = 720; z.par.top = z.op('final_comp').path
        p.par.w = 1280; p.par.h = 720
        z.op('live_perf') or z.create(performCHOP, 'live_perf')
        op('/perform').par.winop = z.path
        try: op('/perform').par.winw = 1280; op('/perform').par.winh = 720
        except Exception as e: log('win size par', e)
        ui.performMode = True
        log('LIVE started pid', os.getpid(), 'perform', ui.performMode, 'folder', F)
    except Exception:
        import traceback; log('ERROR', traceback.format_exc())
    run('args[0]()', check, delayFrames=900)
    run('args[0]()', hb, delayFrames=1800)
def check():
    try:
        z = op('/project1/GENESIS_7140_ZENITH')
        log('CHECK pid', os.getpid(), 'fps', float(z.op('live_perf')['fps']), 'instances', z.op('instance_builder').numSamples,
            'nodes', z.op('node_builder').numSamples, 'perform', ui.performMode)
        z.op('final_comp').save(F + 'live_v1_3_1_frame.jpg')
    except Exception:
        import traceback; log('ERROR check', traceback.format_exc())
def hb():
    try:
        z = op('/project1/GENESIS_7140_ZENITH')
        log('HB fps', round(float(z.op('live_perf')['fps']), 1), 'frame', absTime.frame, 'perform', ui.performMode)
    except Exception as e: log('HB err', e)
    run('args[0]()', hb, delayFrames=1800)
def onStart():
    log('loader start')
    run('args[0]()', go, delayFrames=20)
    return
def onExit():
    log('EXIT clean quit (onExit) pid', os.getpid(), 'frame', absTime.frame)
    return

