# matrix_views_build.py - Matrix Perspective Views (TASK_MATRIX_VIEWS.md, Taylor 2026-10-14 14:55 CT; Overwatch canon locks 15:01 CT)
# Builds /project1/MATRIX_VIEWS from Table DAT /project1/nodes (touchdesigner_nodes.csv). Modeled on genesis_lifefield_v1_0_1_build.py.
#  - Data: H7 = 7x48 binary parity matrix from the 48 odd column masks 3..97 (bit b of mask = row b).
#          H7 syndrome S[i][j] = popcount(col_i XOR col_j) (symmetric, zero diagonal).
#          H14 / Fiedler: loader swaps in Jett's CSVs from DATA_DIR when present:
#             H14_syndrome_48x48.csv  (else H14_parity_14x48.csv -> popcount syndrome)  -> syndrome slot
#             fiedler_adjacency_48x48.csv                                               -> adjacency slot
#          Until then: syndrome slot = H7 syndrome (real, derived) standing in for H14 -> labelled 'PLACEHOLDER-H14';
#          adjacency slot = PLACEHOLDER Hamming-1 graph on H7 columns (A=1 iff S==1), Fiedler-ordered by numpy Laplacian eigvec.
#  - Geometry (native): matrix Table DAT -> DAT to CHOP -> CHOP to TOP (48x48 heightmap texture);
#          heightfield: Grid SOP 144x144 (3x3 pts per cell, flat-topped columns) -> CHOP to SOP displacement (P(1) + Cd from Table DAT 'hf_*' via DAT to CHOP).
#          (TD 2025.33230 has no Displace SOP/POP; CHOP to SOP onto the grid is the native table-driven displace.)
#  - Height ramp (canon): #000000 -> teal(0,.302,.322) @1/phi^2 -> gold(.831,.659,.224) @1/phi (knee) -> white-gold(1,.96,.82) @1
#  - Bonus: 4 spectrum lenses (THERMAL / NVG / UV / XRAY), every knot a canon colour.
#  - ONE distant light, elev atan(1/phi)=31.7175, az 137.508 (TD ry), soft2d shadows; build gated on lightCOMP count == 1 (recursive),
#    Palette arcBallGeometry + cameraViewport loaded with their internal lights stripped.
#  - Cameras: ortho top-down, 45 deg iso, 15 deg grazing, 10 s 360 deg orbit (elev 31.7175).
# Every par set goes through safeset(); every miss prints 'skip ...'.
import math, csv, os
PHI = (1 + 5 ** 0.5) / 2
ELEV = math.degrees(math.atan(1 / PHI)); AZ = 137.508
N = 48; HS = 48 / PHI ** 3                 # height scale 11.331 (u=1 peak)
SUB = 3; NP = N * SUB; SP = 1.0 / SUB      # 3x3 grid points per matrix cell -> flat-topped cell columns (1 unit per cell)
def cell_of(x, z): return int(round(z / SP + (NP - 1) / 2)) // SUB, int(round(x / SP + (NP - 1) / 2)) // SUB   # (row, col)
PLANE = 34 * PHI ** 2                       # 89.0 receiver plane
R_CAM = 34 * PHI                            # 55.0 camera radius
DATA_DIR = 'C:/Users/yetim/Downloads/GENESIS_TD_run/matrix_views/data/'
BLACK = (0.0, 0.0, 0.0); TEAL = (0.000, 0.302, 0.322); GOLD = (0.831, 0.659, 0.224); WGOLD = (1.000, 0.960, 0.820)
K1, K2 = 1 / PHI ** 2, 1 / PHI
LENSES = {   # knots (u, colour); all knots are canon colours
    'CANON':   [(0, BLACK), (K1, TEAL), (K2, GOLD), (1, WGOLD)],
    'THERMAL': [(0, BLACK), (K2, GOLD), (1, WGOLD)],
    'NVG':     [(0, BLACK), (K2, TEAL), (1, WGOLD)],
    'UV':      [(0, BLACK), (1, TEAL)],
    'XRAY':    [(0, WGOLD), (K1, GOLD), (K2, TEAL), (1, BLACK)],
}
VIEWS = {'top': dict(ortho=True), 'iso45': dict(elev=45.0, az=45.0), 'graze15': dict(elev=15.0, az=45.0), 'orbit': dict(elev=ELEV, az=45.0)}
SKIPS = []

def safeset(o, par, val, expr=False):
    try:
        p = getattr(o.par, par)
        if expr: p.expr = val
        else: p.val = val
        return True
    except Exception as e:
        msg = 'skip %s.%s (%s)' % (o.name, par, e); print(msg); SKIPS.append(msg); return False

def ramp(u, lens='CANON'):
    kn = LENSES[lens]; u = min(1.0, max(0.0, u))
    for (u0, c0), (u1, c1) in zip(kn, kn[1:]):
        if u <= u1 + 1e-12:
            w = 0.0 if u1 == u0 else (u - u0) / (u1 - u0); return tuple(c0[j] + (c1[j] - c0[j]) * w for j in range(3))
    return kn[-1][1]

def read_matrix(path):
    rows = []
    for r in csv.reader(open(path, encoding='utf-8-sig')):
        vals = []
        for c in r:
            try: vals.append(float(c))
            except ValueError: pass
        if vals: rows.append(vals)
    w = max(len(r) for r in rows)
    rows = [r[-w:] for r in rows if len(r) >= w]
    # drop a leading index column / header-index row if the matrix came with labels
    if len(rows) == N + 1: rows = rows[1:]
    if rows and len(rows[0]) == N + 1: rows = [r[1:] for r in rows]
    return rows

def load_data(nodes):
    import numpy as np
    hdr = [c.val for c in nodes.row(0)]; nc = {h: i for i, h in enumerate(hdr)}
    masks = sorted(int(float(nodes[r, nc['mask']].val)) for r in range(1, nodes.numRows))
    H7 = [[(m >> b) & 1 for m in masks] for b in range(7)]
    S7 = [[bin(a ^ b).count('1') for b in masks] for a in masks]
    D = {'masks': masks, 'H7': H7, 'S7': S7, 'source': {}}
    # ---- syndrome slot ----
    if os.path.exists(DATA_DIR + 'H14_syndrome_48x48.csv'):
        D['syn'] = read_matrix(DATA_DIR + 'H14_syndrome_48x48.csv'); D['syn_label'] = 'H14 SYNDROME (Jett CSV)'; D['syn_placeholder'] = False
        D['source']['syndrome'] = DATA_DIR + 'H14_syndrome_48x48.csv'
    elif os.path.exists(DATA_DIR + 'H14_parity_14x48.csv'):
        P = read_matrix(DATA_DIR + 'H14_parity_14x48.csv'); cols = [int(''.join(str(int(P[b][j])) for b in range(len(P))), 2) for j in range(N)]
        D['syn'] = [[bin(a ^ b).count('1') for b in cols] for a in cols]; D['syn_label'] = 'H14 SYNDROME (popcount, Jett H14 parity CSV)'; D['syn_placeholder'] = False
        D['source']['syndrome'] = DATA_DIR + 'H14_parity_14x48.csv'
    else:
        D['syn'] = S7; D['syn_label'] = 'H7 SYNDROME popcount(col_i^col_j) | H14 PLACEHOLDER (awaiting Jett CSV)'; D['syn_placeholder'] = True
        D['source']['syndrome'] = 'derived: H7 from masks 3..97 (stand-in for H14)'
    # ---- adjacency slot ----
    if os.path.exists(DATA_DIR + 'fiedler_adjacency_48x48.csv'):
        D['adj'] = read_matrix(DATA_DIR + 'fiedler_adjacency_48x48.csv'); D['adj_label'] = 'FIEDLER ADJACENCY (Jett CSV)'; D['adj_placeholder'] = False
        D['source']['adjacency'] = DATA_DIR + 'fiedler_adjacency_48x48.csv'; D['lambda2'] = None; D['fiedler_order'] = None
    else:
        A = np.array([[1 if S7[i][j] == 1 else 0 for j in range(N)] for i in range(N)])
        L = np.diag(A.sum(1)) - A; w, v = np.linalg.eigh(L); f = v[:, 1]
        if f[0] > 0: f = -f
        order = sorted(range(N), key=lambda i: (round(float(f[i]), 12), masks[i]))
        D['adj'] = [[int(A[order[i], order[j]]) for j in range(N)] for i in range(N)]
        D['lambda2'] = float(w[1]); D['fiedler_order'] = [masks[i] for i in order]
        D['adj_label'] = 'FIEDLER ADJACENCY PLACEHOLDER (Hamming-1 on H7 cols, Overwatch rule)'; D['adj_placeholder'] = True
        D['source']['adjacency'] = 'PLACEHOLDER: A=1 iff popcount(col_i^col_j)==1, Fiedler order of L=D-A'
    return D

def build(parent=None):
    parent = parent or op('/project1')
    old = parent.op('MATRIX_VIEWS')
    if old: old.destroy()
    z = parent.create(containerCOMP, 'MATRIX_VIEWS'); z.par.w = 1280; z.par.h = 720
    D = load_data(op('/project1/nodes'))
    z.store('data_meta', {k: D[k] for k in ('syn_label', 'adj_label', 'syn_placeholder', 'adj_placeholder', 'lambda2', 'fiedler_order', 'source', 'masks')})
    # ---- H7 parity table (7x48) ----
    th = z.create(tableDAT, 'H7_parity_7x48'); th.clear()
    for r in D['H7']: th.appendRow(r)
    # ---- matrices: Table DAT -> DAT to CHOP -> CHOP to TOP ----
    geos = {}
    grid_tmp = None
    for key in ('syn', 'adj'):
        M = D[key]; vmax = max(max(r) for r in M) or 1.0
        t = z.create(tableDAT, 'mat_' + key); t.clear()
        for r in M: t.appendRow(r)
        dc = z.create(dattoCHOP, 'chop_' + key); safeset(dc, 'dat', t.path); safeset(dc, 'output', 'chanpercol'); safeset(dc, 'firstrow', 'values'); safeset(dc, 'firstcolumn', 'values')
        tx = z.create(choptoTOP, 'tex_' + key); safeset(tx, 'chop', dc.path); safeset(tx, 'dataformat', 'r'); safeset(tx, 'layout', 'rowscropped')
        # heightfield geometry: Grid SOP -> CHOP to SOP (P(1), Cd from hf table)
        g = z.create(geometryCOMP, 'geo_' + key)
        for c in g.children: c.destroy()
        gr = g.create(gridSOP, 'grid')
        for pn, v in (('orient', 'zx'), ('sizex', (NP - 1) * SP), ('sizey', (NP - 1) * SP), ('rows', NP), ('cols', NP), ('normals', True)): safeset(gr, pn, v)
        gr.cook(force=True)
        hf = z.create(tableDAT, 'hf_' + key); hf.clear(); hf.appendRow(['ty', 'r', 'g', 'b', 'row', 'col'])
        for p in gr.points:
            row, col = cell_of(p.x, p.z)
            u = M[row][col] / vmax; c = ramp(u)
            hf.appendRow([u * HS, c[0], c[1], c[2], row, col])
        hc = z.create(dattoCHOP, 'hfchop_' + key); safeset(hc, 'dat', hf.path); safeset(hc, 'output', 'chanpercol'); safeset(hc, 'firstrow', 'names'); safeset(hc, 'firstcolumn', 'values')
        safeset(hc, 'extractcols', 'bynames'); safeset(hc, 'colnames', 'ty r g b')
        cs = g.create(choptoSOP, 'displace'); cs.inputConnectors[0].connect(gr)
        for pn, v in (('chop', hc.path), ('chanscope', 'ty r g b'), ('attscope', 'P(1) Cd(0) Cd(1) Cd(2)'), ('mapping', 'onetoone'), ('compnml', True)): safeset(cs, pn, v)
        cs.render = True; cs.display = True
        z.store('vmax_' + key, vmax)
        geos[key] = g
    # ---- material: Phong, point colour = height ramp; dimmer 1/sin(elev) so a flat lit cell shows its ramp colour exactly ----
    m = z.create(phongMAT, 'mat_terrain')
    for pn, v in (('diffr', 1), ('diffg', 1), ('diffb', 1), ('specr', 0), ('specg', 0), ('specb', 0), ('ambr', 0), ('ambg', 0), ('ambb', 0), ('emitr', 0), ('emitg', 0), ('emitb', 0), ('applypointcolor', True), ('shadowstrength', 1)): safeset(m, pn, v)
    for g in geos.values(): safeset(g, 'material', m.path)
    mp = z.create(phongMAT, 'mat_plane')
    for pn, v in (('diffr', 0), ('diffg', 0), ('diffb', 0), ('specr', 0), ('specg', 0), ('specb', 0)): safeset(mp, pn, v)
    gp = z.create(geometryCOMP, 'geo_plane')
    for c in gp.children: c.destroy()
    s = gp.create(gridSOP, 'shape')
    for pn, v in (('sizex', PLANE), ('sizey', PLANE), ('orient', 'zx'), ('rows', 2), ('cols', 2), ('ty', -0.02)): safeset(s, pn, v)
    s.render = True; s.display = True; safeset(gp, 'material', mp.path)
    # ---- the ONE light ----
    lt = z.create(lightCOMP, 'key_light')
    fx = -math.cos(math.radians(ELEV)) * math.sin(math.radians(AZ)); fy = -math.sin(math.radians(ELEV)); fz = -math.cos(math.radians(ELEV)) * math.cos(math.radians(AZ))
    for pn, v in (('lighttype', 'distant'), ('rx', -ELEV), ('ry', AZ), ('tx', -fx * 60), ('ty', -fy * 60), ('tz', -fz * 60), ('dimmer', 1 / math.sin(math.radians(ELEV))), ('cr', 1), ('cg', 1), ('cb', 1),
                  ('shadowtype', 'soft2d'), ('lightsize1', 0.05), ('lightsize2', 0.05), ('maxshadowsoftness', 1), ('filtersamples', 32), ('shadowresolution1', 4096), ('shadowresolution2', 4096),
                  ('projection', 'ortho'), ('orthowidth', PLANE), ('near', 1), ('far', 200)): safeset(lt, pn, v)
    lt.store('forward_expected', (fx, fy, fz))
    # ---- cameras ----
    tgt = z.create(nullCOMP, 'look_target'); safeset(tgt, 'ty', HS / 3)
    for nm, v in VIEWS.items():
        cam = z.create(cameraCOMP, 'cam_' + nm); safeset(cam, 'far', 400); safeset(cam, 'near', 0.5)
        if v.get('ortho'):
            for pn, val in (('projection', 'ortho'), ('orthowidth', (N - 1) * 1.12 * 16 / 9), ('tx', 0), ('ty', 80), ('tz', 0), ('rx', -90), ('ry', 0)): safeset(cam, pn, val)
        elif nm == 'orbit':
            e = math.radians(v['elev'])
            safeset(cam, 'tx', "%f*math.sin(math.radians(%f+36.0*(absTime.seconds-parent().fetch('orbit_t0',0))))" % (R_CAM * math.cos(e), v['az']), expr=True)
            safeset(cam, 'tz', "%f*math.cos(math.radians(%f+36.0*(absTime.seconds-parent().fetch('orbit_t0',0))))" % (R_CAM * math.cos(e), v['az']), expr=True)
            safeset(cam, 'ty', HS / 3 + R_CAM * math.sin(e)); safeset(cam, 'lookat', tgt.path)
        else:
            e, a = math.radians(v['elev']), math.radians(v['az'])
