        if core.sum() > 20:
            ys, xs = np.nonzero(core)
            cpx = W_/2 + (SH['cx'] - SH['ctr'][0]) * ppu; cpy = H_/2 - (SH['cz'] - SH['ctr'][1]) * ppu
            mx, my = xs.mean(), ys.mean(); dwx, dwz = (mx - cpx) / ppu, -(my - cpy) / ppu
