                       direction_measured_deg=round(ang_m, 3), direction_expected_deg=round(ang_e, 3), direction_error_deg=round(abs((ang_m - ang_e + 180) % 360 - 180), 3),
                       shadow_length_units=round(2 * math.hypot(dwx, dwz), 3), shadow_length_expected=round(SH['exp_len'], 3))
            px_, pz_ = -math.sin(math.radians(ang_m)), math.cos(math.radians(ang_m)); widths = []
