                    if 0 <= x < W_ and 0 <= y < H_: prof.append((t, float(1 - ratio[y, x])))
                d90 = next((t for t, d in prof if d < 0.9), None); d10 = next((t for t, d in prof if d < 0.1), None)
                if d90 is not None and d10 is not None: widths.append(d10 - d90)
