        pick = min(ok, key=lambda r: abs(r['penumbra_px_probe'] - 5)) if ok else min(SH['results'], key=lambda r: abs((r.get('penumbra_px_probe') or 0) - 5))
        lt.par.lightsize1 = pick['lightsize']; lt.par.lightsize2 = pick['lightsize']
