def img_stats(z, lens):
    import numpy as np
    a = z.op('final').numpyArray()[:, :, :3]; Yl = 0.2126*a[:, :, 0] + 0.7152*a[:, :, 1] + 0.0722*a[:, :, 2]
    sc = z.op('shoulder').numpyArray()[:, :, :3]
    st = {'clipped_pct': round(float((a >= 0.995).any(axis=2).mean() * 100), 4), 'mean_lum': round(float(Yl.mean()), 4), 'contrast_rms': round(float(Yl.std()), 4), 'p99_lum': round(float(np.percentile(Yl, 99)), 4)}
    # palette fidelity: chroma-normalised rendered terrain pixels (HUD excluded) vs nearest point of the active lens ramp, CIEDE2000 on 1500 random lit pixels
    ys, xs = np.nonzero((sc.max(axis=2) > 0.03))
    rnd = random.Random(7); idx = [rnd.randrange(len(ys)) for _ in range(min(1500, len(ys)))] if len(ys) else []
    rs = [norm(ramp(i / 255.0, lens)) for i in range(256) if max(ramp(i / 255.0, lens)) > 0.03]
    d = sorted(min(de2000(norm([float(v) for v in sc[ys[k], xs[k]]]), r) for r in rs[::4]) for k in idx)
    if d: st.update(render_dE2000_vs_ramp_p50=round(d[len(d)//2], 3), render_dE2000_vs_ramp_p95=round(d[int(len(d)*0.95)], 3), render_dE2000_samples=len(d))
    ra = z.op('render').numpyArray()[..., :3]; band = np.concatenate([ra[:8].reshape(-1, 3), ra[-8:].reshape(-1, 3)]); bgc = np.median(band, axis=0).tolist()
    st['background_rendered_dE2000_vs_black'] = round(de2000((0, 0, 0), bgc), 3)
    ha = z.op('hud').numpyArray(); m = ha[..., 3] > 0.95
    if m.any(): hp = (ha[..., :3][m] / ha[..., 3][m][:, None]).mean(0).tolist(); st['hud_rendered_dE2000_vs_gold'] = round(de2000(GOLD, hp), 3)
    lt = z.op('key_light'); st['light'] = [round(float(getattr(lt.par, p).eval()), 6) for p in ('rx', 'ry', 'rz', 'dimmer', 'cr', 'cg', 'cb')]
    st['light_count'] = len(z.findChildren(type=lightCOMP) + z.findChildren(type=ambientlightCOMP) + z.findChildren(type=environmentlightCOMP))
    return st
