def set_view(z, key, view, lens='CANON'):
    """Switch matrix slot ('syn'/'adj'), camera view and lens; rewrites hf colours for the lens; HUD = measured data values."""
    meta = z.fetch('data_meta'); hf = z.op('hf_' + key); vmax = z.fetch('vmax_' + key)
    for r in range(1, hf.numRows):
        c = ramp(float(hf[r, 'ty'].val) / HS, lens); hf[r, 'r'] = c[0]; hf[r, 'g'] = c[1]; hf[r, 'b'] = c[2]
    z.op('render').par.geometry = z.op('geo_' + key).path + ' ' + z.op('geo_plane').path
    z.op('render').par.camera = z.op('cam_' + view).path
    t = z.op('mat_' + key); vals = [float(t[i, j].val) for i in range(t.numRows) for j in range(t.numCols)]
    lt = z.op('key_light')
    l1 = (meta['syn_label'] if key == 'syn' else meta['adj_label'])
    l2 = '48x48 | min %g max %g mean %.4f | nonzero %d' % (min(vals), max(vals), sum(vals) / len(vals), sum(1 for v in vals if v))
