    l3 = 'VIEW %s | LENS %s | LIGHT 1 distant el %.4f az %.3f' % (view.upper(), lens, -lt.par.rx.eval(), lt.par.ry.eval())
    z.op('hud').par.text = '\n'.join((l1, l2, l3))
